type StoredFinding = Finding & { id: string; organizationId: string; projectId: string; scanId: string; status: 'OPEN' | 'RESOLVED' | 'SUPPRESSED' | 'ACCEPTED_RISK'; firstDetected: string; lastDetected: string; reason?: string };
