const empty: Store = { organizations: [], users: [], memberships: [], projects: [], scans: [], findings: [], aiComponents: [], audit: [], pilots: [], feedback: [], featureRequests: [], subscriptions: [], usageRecords: [], billingAuditEvents: [], commercialEvents: [], leads: [], processedWebhookEventIds: [], organizationDomains: {} };
