const here = path.dirname(fileURLToPath(import.meta.url)); const dataFile = process.env.PLATFORM_DATA_FILE ? path.resolve(process.env.PLATFORM_DATA_FILE) : path.resolve(here, '../../../../.data/platform.json');
const APP_VERSION: string = (() => { try { return (JSON.parse(readFileSync(path.resolve(here, '../../../../package.json'), 'utf8')) as { version?: string }).version ?? '0.0.0'; } catch { return '0.0.0'; } })();
const limits = { body: 5_000_000, findings: 10_000, evidence: 20_000 };
async function readStore(): Promise<Store> { try { return { ...empty, ...JSON.parse(await fs.readFile(dataFile, 'utf8')) } as Store; } catch { return structuredClone(empty); } }
async function writeStore(store: Store): Promise<void> { await fs.mkdir(path.dirname(dataFile), { recursive: true }); await fs.writeFile(dataFile, `${JSON.stringify(store, null, 2)}\n`); }
function id(prefix: string): string { return `${prefix}_${randomBytes(8).toString('hex')}`; }
function hash(value: string): string { return createHash('sha256').update(value).digest('hex'); }
function safeProject(project: Project): Omit<Project, 'tokenHash'> { const { tokenHash: _hidden, ...safe } = project; return safe; }
function score(findings: StoredFinding[]): number { const weights: Record<Severity, number> = { LOW: 1, MEDIUM: 4, HIGH: 12, CRITICAL: 30 }; return Math.max(0, 100 - findings.filter(item => item.status === 'OPEN').reduce((total, item) => total + weights[item.severity], 0)); }
function json(response: http.ServerResponse, status: number, value: unknown, origin: string): void { response.writeHead(status, { 'content-type': 'application/json', 'x-content-type-options': 'nosniff', 'x-frame-options': 'DENY', 'referrer-policy': 'no-referrer', 'content-security-policy': "default-src 'none'; frame-ancestors 'none'", 'access-control-allow-origin': origin }); response.end(JSON.stringify(value)); }
async function readBody(request: http.IncomingMessage): Promise<Record<string, unknown>> { let raw = ''; for await (const chunk of request) { raw += chunk; if (raw.length > limits.body) throw new Error('request body exceeds 5 MB'); } return JSON.parse(raw || '{}') as Record<string, unknown>; }
function authToken(request: http.IncomingMessage): string | undefined { const value = request.headers.authorization; return value?.startsWith('Bearer ') ? value.slice(7) : undefined; }
function header(request: http.IncomingMessage, name: string): string | undefined { const value = request.headers[name]; return typeof value === 'string' ? value : undefined; }
function audit(store: Store, type: string, organizationId: string, actorId?: string, resource?: string, metadata?: Record<string, string>): void { store.audit.push({ id: id('audit'), type, organizationId, actorId, resource, timestamp: new Date().toISOString(), metadata }); }
function membership(store: Store, organizationId: string, request: http.IncomingMessage): Membership | undefined { const userId = request.headers['x-user-id']; if (typeof userId !== 'string') return undefined; return store.memberships.find(item => item.organizationId === organizationId && item.userId === userId); }
export function can(member: { role: Role } | undefined, roles: Role[]): member is { role: Role } { return Boolean(member && roles.includes(member.role)); }
export function verifySignature(payload: string, signature: string | undefined, secret: string | undefined): boolean { if (!signature || !secret) return false; const expected = `sha256=${createHmac('sha256', secret).update(payload).digest('hex')}`; return signature.length === expected.length && timingSafeEqual(Buffer.from(signature), Buffer.from(expected)); }
function emitCommercial(store: Store, organizationId: string, type: CommercialEventType, metadata?: Record<string, string>): void { store.commercialEvents.push(createCommercialEvent(organizationId, type, metadata)); }
/** Lazily starts a trial the first time an organization is looked up; auto-expires a trial whose window has passed. Never deletes data - only changes plan/status. */
function effectiveSubscription(store: Store, organizationId: string): Subscription { let subscription = store.subscriptions.find(item => item.organizationId === organizationId); if (!subscription) { subscription = startTrial(organizationId, 'TEAM'); store.subscriptions.push(subscription); store.billingAuditEvents.push(createBillingAuditEvent(organizationId, 'TRIAL_STARTED', { planId: subscription.planId })); emitCommercial(store, organizationId, 'TRIAL_STARTED', { planId: subscription.planId }); } if (isTrialExpired(subscription)) { const expired = expireTrial(subscription); store.subscriptions = store.subscriptions.map(item => item.id === expired.id ? expired : item); store.billingAuditEvents.push(createBillingAuditEvent(organizationId, 'TRIAL_EXPIRED')); subscription = expired; } return subscription; }
function usageSnapshot(store: Store, organizationId: string, metric: UsageMetric, capability: NumericCapability, subscription: Subscription) { const period = currentPeriod(); const used = usageForPeriod(store.usageRecords, organizationId, metric, period); const limit = getLimit(subscription.planId, capability, subscription.limitOverrides); return checkLimit(capability, used, limit); }
/** Internal admin authorization is separate from organization roles: a tenant OWNER/ADMIN must never see cross-tenant commercial metrics. */
function isSystemAdmin(request: http.IncomingMessage): boolean { const provided = header(request, 'x-admin-token'); const expected = process.env.ADMIN_TOKEN; if (!provided || !expected || provided.length !== expected.length) return false; return timingSafeEqual(Buffer.from(provided), Buffer.from(expected)); }
